// GENERATED by scripts/sync-core.mjs from js/core. Edit the original, then run `npm run sync`.
// Daily challenge generation. A challenge is generated from a seed, then
// checked for solvability before it can be published. Generation is
// deterministic: the same seed, theme word and dictionary give the same grid.
import { createRng, randInt, shuffle, weightedPick } from './rng.js';
import { TILE_COUNT, neighbours, wordFromPath } from './grid.js';
import { solve, hasWord } from './solver.js';
import { RULES_VERSION, wordScore, THEME_WORD_BONUS } from './scoring.js';

export const TIME_LIMIT_S = 300;

// Letter weights for filling tiles (roughly English letter frequency, with
// rare letters damped so grids stay playable).
const FILL_WEIGHTS = Object.entries({
  e: 12, a: 9, i: 8, o: 8, t: 9, n: 7, s: 7, r: 7, l: 5, h: 4, d: 4, u: 4, c: 3,
  m: 3, p: 3, g: 3, b: 2, f: 2, y: 2, w: 2, k: 1, v: 1, x: 0.4, j: 0.3, q: 0.3, z: 0.3
});
const VOWELS = new Set(['a', 'e', 'i', 'o', 'u']);

// Hidden "word of the day" candidates (6–8 letters, no q). Leaning on food,
// drink, music and a night out, to suit the pilot's merchants. Any word not
// in the dictionary is skipped.
export const THEME_WORDS = [
  'theatre', 'concert', 'kitchen', 'pudding', 'biscuit', 'brunch', 'coffee', 'espresso',
  'festival', 'harmony', 'melody', 'rhythm', 'chorus', 'trumpet', 'guitar', 'cabaret',
  'comedy', 'cinema', 'gallery', 'museum', 'market', 'bakery', 'pastry', 'noodles',
  'dumpling', 'curries', 'sorbet', 'gelato', 'pickles', 'teapot', 'saucer',
  'castle', 'elephant', 'bridge', 'station', 'borough', 'garden', 'parkland',
  'lantern', 'encore', 'ticket', 'dancer', 'singer', 'drummer', 'pianist',
  'velvet', 'sparkle', 'evening', 'sunset', 'weekend', 'holiday', 'picnic', 'carnival'
];

export const DEFAULT_LIMITS = Object.freeze({
  minWords: 40,
  maxWords: 400,
  minLongWord: 6, // at least one word this long
  minVowels: 4,
  maxVowels: 7
});

function randomPath(rng, length) {
  // Random self-avoiding walk with backtracking.
  const start = shuffle(rng, [...Array(TILE_COUNT).keys()]);
  const path = [];
  const used = new Set();
  function walk(i) {
    path.push(i);
    used.add(i);
    if (path.length === length) return true;
    for (const n of shuffle(rng, neighbours(i))) {
      if (!used.has(n) && walk(n)) return true;
    }
    path.pop();
    used.delete(i);
    return false;
  }
  for (const s of start) if (walk(s)) return path;
  return null;
}

function fillTiles(rng, themeWord) {
  const tiles = new Array(TILE_COUNT).fill(null);
  if (themeWord) {
    const path = randomPath(rng, themeWord.length);
    path.forEach((i, k) => (tiles[i] = themeWord[k]));
  }
  for (let i = 0; i < TILE_COUNT; i++) if (!tiles[i]) tiles[i] = weightedPick(rng, FILL_WEIGHTS);
  return tiles;
}

function pickStar(rng, tiles) {
  const candidates = tiles
    .map((t, i) => [t, i])
    .filter(([t]) => 'aeionrtsldh'.includes(t))
    .map(([, i]) => i);
  const pool = candidates.length ? candidates : [...Array(TILE_COUNT).keys()];
  return pool[randInt(rng, pool.length)];
}

/** A word's best score: through the star tile when possible. */
function bestScore(entry) {
  return wordScore(entry.word, Boolean(entry.starPath));
}

/** Check a candidate grid. Returns {ok, reason, solutions}. */
export function checkSolvable(tiles, star, words, { themeWord = null, limits = DEFAULT_LIMITS } = {}) {
  const vowels = tiles.filter((t) => VOWELS.has(t)).length;
  if (vowels < limits.minVowels || vowels > limits.maxVowels) return { ok: false, reason: 'vowel_balance' };
  const solutions = solve(tiles, words, star);
  if (solutions.length < limits.minWords) return { ok: false, reason: 'too_few_words', solutions };
  if (solutions.length > limits.maxWords) return { ok: false, reason: 'too_many_words', solutions };
  if (!solutions.some((s) => s.word.length >= limits.minLongWord)) return { ok: false, reason: 'no_long_word', solutions };
  if (themeWord && !solutions.some((s) => s.word === themeWord)) return { ok: false, reason: 'theme_word_missing', solutions };
  return { ok: true, reason: null, solutions };
}

/**
 * Target score for the "target score" points award: about 7% of the best
 * possible, in steps of 5, between 40 and 150. A typical five-minute game
 * finds 15–25 words, so most regular players can reach it.
 */
export function targetScore(maxScore) {
  return Math.max(40, Math.min(150, Math.round((maxScore * 0.07) / 5) * 5));
}

/**
 * Generate a challenge.
 *   date: 'YYYY-MM-DD' (the challenge id)
 *   words: sorted dictionary array
 *   salt: server secret mixed into the seed so grids can't be predicted ahead of publication
 *   themeWord: optional hidden word that must be traceable in the grid
 * Returns the full definition (including the solution list), or throws.
 * @param {{date: string, words: string[], salt?: string, themeWord?: string|null, themeHint?: string|null, maxAttempts?: number, limits?: typeof DEFAULT_LIMITS}} opts
 */
export function generateChallenge({ date, words, salt = '', themeWord = null, themeHint = null, maxAttempts = 400, limits = DEFAULT_LIMITS }) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('invalid date');
  let theme = themeWord ? themeWord.toLowerCase() : null;
  if (theme && (!/^[a-pr-z]+$/.test(theme) || theme.length < 6 || theme.length > 8 || !hasWord(words, theme))) {
    throw new Error('theme word must be a 6–8 letter dictionary word without q');
  }
  if (!theme) {
    const pool = THEME_WORDS.filter((w) => w.length >= 6 && w.length <= 8 && hasWord(words, w));
    theme = pool.length ? pool[randInt(createRng(`${salt}|theme|${date}`), pool.length)] : null;
  }
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const rng = createRng(`${salt}|${date}|${theme}|${attempt}`);
    const tiles = fillTiles(rng, theme);
    const star = pickStar(rng, tiles);
    const check = checkSolvable(tiles, star, words, { themeWord: theme, limits });
    if (!check.ok) continue;
    const solutions = check.solutions.map((s) => ({ word: s.word, score: bestScore(s), path: s.starPath ?? s.path }));
    const maxScore = solutions.reduce((a, s) => a + s.score, 0) + (theme ? THEME_WORD_BONUS : 0);
    return {
      id: date,
      date,
      rules_version: RULES_VERSION,
      size: 4,
      tiles,
      star,
      theme_word: theme,
      theme_hint: themeHint,
      time_limit_s: TIME_LIMIT_S,
      word_count: solutions.length,
      max_score: maxScore,
      target_score: targetScore(maxScore),
      attempt,
      solutions
    };
  }
  throw new Error('no solvable grid found');
}

/** What players see before and during play: no solutions, no theme word. */
export function publicChallenge(def) {
  const { solutions, theme_word, attempt, ...rest } = def;
  return { ...rest, theme_length: theme_word ? theme_word.length : null };
}

/** Lookup table word -> max score, for validating submissions. */
export function solutionIndex(def) {
  return new Map(def.solutions.map((s) => [s.word, s]));
}

